// Стандарт С++20:

#include <iostream>
#include <format>
#include <string>                                           // Подключение заголовочного файла для применения класса std::string для работы со строками;
#include <string_view>                                      // Подключение заголовочного файла для подключения взгляда на строки и определения их размера;

int main()
{
    std::string animal{"медведь"};                        // Инициализация объекта класса string строки строковым литералом;
    constexpr std::string_view bird{"воробей"};          // Объект класса string_view накладывает взгляд на строковый литерал, при этом память не тратится на копирование строки. constexpr - дает компилятору команду сначала вычислить объект на этапе компиляции, до того как будет запущена программа;
    std::cout << std::format("{} и {}\n", animal, bird); // Объект cout с помощью оператора << выводит строку, отформатированную из содержимого объекта строки (данные которого лежат в куче) и объекта (который просто указывает на адрес строкового литерала);
    std::cout << "Введите вид животного: ";
    std::getline(std::cin, animal);                   // Функция getline() принимает 1 аргумент - объект ввода и 2 аргумент - ссылку на объект строки, куда запишется строка, введенная с клавиатуры до символа новой строки \n, который функция отбрасывает;
    std::string_view ps = animal;                        // Объект класса string_view накладывает взгляд на объект строки;
    std::cout << std::format("{}!\n", ps);       // Объект cout с помощью оператора << выводит отформатированную строку со строкой, на которую направлен взгляд ps;
    std::cout << "До копирования памяти:\n";

    const char* animal_addr1 = animal.data();               // Инициализация указателя типа char, защищенного от случайного изменения, адресом первого символа строки в памяти (куче), на который ссылается объект строки, методом .data() класса string;
    const char* ps_addr = ps.data();                        // Инициализация указателя типа char, защищенного от случайного изменения, адресом первого символа строки в памяти (куче), на которую направлен взгляд ps, методом .data() класса string_view;

    std::cout << std::format("{} по адресу {:p}\n",      // Объект cout с помощью оператора << выводит отформатированную строку с содержимым объекта строки и ее адресом, который хранится в указателе на первый символ в строке.
        animal, static_cast<const void*>(animal_addr1));// static_cast<const void*> - явно преобразует тип указателя в универсальный тип (void*), чтобы функция format() смогла отобразить адрес в шестнадцатеричном виде через спецификатор {:p};
    std::cout << std::format("{} по адресу {:p}\n",      // Объект cout с помощью оператора << выводит отформатированную строку со строкой, на которую наложен взгляд объекта класса string_view и ее адресом, который хранится в указателе на первый символ в строке;
        ps, static_cast<const void*>(ps_addr));         // static_cast<const void*> - явно преобразует тип указателя в универсальный тип (void*), чтобы функция format() смогла отобразить адрес в шестнадцатеричном виде через спецификатор {:p};

    std::string animal_copy = animal;                    // Инициализация нового объекта строки копией данных из объекта animal, в памяти создается независимый дубликат текста;

    std::cout << "После копирования памяти:\n";
    const char* animal_addr2 = animal.data();               // Инициализация указателя типа char, защищенного от случайного изменения, адресом первого символа строки в памяти (куче), на который ссылается объект строки, методом .data() класса string;
    const char* copy_addr = animal_copy.data();             // Инициализация указателя типа char, защищенного от случайного изменения, адресом первого символа строки в памяти (куче), на который ссылается объект строки (копия объекта animal), методом .data() класса string;

    std::cout << std::format("{} по адресу {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку с содержимым объекта строки и ее адресом, который хранится в указателе на первый символ в строке.
        animal, static_cast<const void*>(animal_addr2));  // static_cast<const void*> - явно преобразует тип указателя в универсальный тип (void*), чтобы функция format() смогла отобразить адрес в шестнадцатеричном виде через спецификатор {:p};
    std::cout << std::format("{} по адресу {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку с содержимым объекта строки и ее адресом, который хранится в указателе на первый символ в строке.
        animal_copy, static_cast<const void*>(copy_addr));// static_cast<const void*> - явно преобразует тип указателя в универсальный тип (void*), чтобы функция format() смогла отобразить адрес в шестнадцатеричном виде через спецификатор {:p};
}



